import time
import unittest

import launch
import launch_ros.actions
import launch_testing.actions
import launch_testing.markers
import pytest
import rclpy
from std_msgs.msg import Int32


@pytest.mark.launch_test
def generate_test_description():
    echo_node = launch_ros.actions.Node(
        package='echo_pkg',
        executable='echo_node',
        name='echo_node',
    )
    return launch.LaunchDescription([
        echo_node,
        launch_testing.actions.ReadyToTest(),
    ]), {'echo_node': echo_node}


class TestEchoNode(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        rclpy.init()

    @classmethod
    def tearDownClass(cls):
        rclpy.shutdown()

    def setUp(self):
        self.node = rclpy.create_node('test_echo_node')

    def tearDown(self):
        self.node.destroy_node()

    def test_value_republished_on_out(self, echo_node, proc_output):
        received = []
        sub = self.node.create_subscription(
            Int32, '/out', lambda msg: received.append(msg.data), 10)
        pub = self.node.create_publisher(Int32, '/in', 10)

        try:
            # Wait for discovery to complete so the published message
            # is not lost before echo_node's subscription is matched.
            deadline = time.time() + 10.0
            while pub.get_subscription_count() == 0 and time.time() < deadline:
                rclpy.spin_once(self.node, timeout_sec=0.1)
            self.assertGreater(
                pub.get_subscription_count(), 0,
                'echo_node never subscribed to /in')

            msg = Int32()
            msg.data = 42

            deadline = time.time() + 10.0
            while not received and time.time() < deadline:
                pub.publish(msg)
                rclpy.spin_once(self.node, timeout_sec=0.5)

            self.assertTrue(len(received) > 0, 'No message received on /out')
            self.assertEqual(received[0], 42)
        finally:
            self.node.destroy_subscription(sub)
            self.node.destroy_publisher(pub)

